public class DateTimeFormatter_parseInto_TriageGen0Test {

    @Test(expected = IllegalArgumentException.class)
    public void testParseInto_NullInstant_ThrowsException() {
        DateTimeFormatter formatter = new DateTimeFormatterBuilder().appendInstant().toFormatter();
        formatter.parseInto(null, "2023-01-01", 0);
    }

    @Test
    public void testParseInto_StandardFormat_ReturnsNewPosition() {
        // Using a real builder to get a functional parser/formatter
        DateTimeFormatter formatter = new DateTimeFormatterBuilder()
                .appendYear()
                .appendLiteral('-')
                .appendMonthOfYear()
                .appendLiteral('-')
                .appendDayOfMonth()
                .toFormatter();

        // ReadWritableInstant implementation (Instant is not writable, 
        // in Joda, MutableDateTime is typically used for ReadWritableInstant)
        org.joda.time.MutableDateTime instant = new org.joda.time.MutableDateTime(2020, 1, 1, 0, 0, 0, 0);

        String text = "2023-05-10";
        int position = 0;

        int newPos = formatter.parseInto(instant, text, position);

        // 2023-05-10 is 10 chars long
        Assert.assertEquals(10, newPos);
        Assert.assertEquals(2023, instant.getYear());
        Assert.assertEquals(5, instant.getMonthOfYear());
        Assert.assertEquals(10, instant.getDayOfMonth());
    }

    @Test
    public void testParseInto_WithOffsetParsed_UpdatesChronology() {
        // Test the branch: if (iOffsetParsed && bucket.getOffsetInteger() != null)
        DateTimeFormatter formatter = new DateTimeFormatterBuilder()
                .appendYear()
                .appendLiteral('-')
                .appendMonthOfYear()
                .appendLiteral('-')
                .appendDayOfMonth()
                .appendLiteral(' ')
                .appendHourOfDay()
                .appendLiteral(':')
                .appendMinuteOfHour()
                .appendLiteral(' ')
                .appendOffset("+HH:mm")
                .withOffsetParsed()
                .toFormatter();

        org.joda.time.MutableDateTime instant = new org.joda.time.MutableDateTime();
        String text = "2023-01-01 12:00 +02:00";

        formatter.parseInto(instant, text, 0);

        // The offset +02:00 should be applied to the chronology/zone
        Assert.assertEquals("+02:00", instant.getZone().getID());
    }

    @Test
    public void testParseInto_WithExplicitZone_SetsZone() {
        // Test the branch: if (iZone != null) { instant.setZone(iZone); }
        DateTimeZone targetZone = DateTimeZone.forID("America/New_York");
        DateTimeFormatter formatter = new DateTimeFormatterBuilder()
                .appendYear()
                .appendLiteral('-')
                .appendMonthOfYear()
                .appendLiteral('-')
                .appendDayOfMonth()
                .toFormatter()
                .withZone(targetZone);

        org.joda.time.MutableDateTime instant = new org.joda.time.MutableDateTime();
        String text = "2023-01-01";

        formatter.parseInto(instant, text, 0);

        Assert.assertEquals(targetZone, instant.getZone());
    }

    @Test
    public void testParseInto_BucketZoneOnly_UpdatesChronology() {
        // Test the branch: else if (bucket.getZone() != null)
        // This occurs when the parser itself provides a zone via the bucket, 
        // but iOffsetParsed is false.

        // We use a custom parser via Mockito to simulate bucket.getZone() returning a value
        DateTimeParser mockParser = mock(DateTimeParser.class);
        DateTimeFormatterBuilder builder = new DateTimeFormatterBuilder().appendPattern("yyyy");

        // Since we cannot easily inject a mock parser into the private field of a real DateTimeFormatter 
        // without reflection, we simulate the logic via a pattern that includes a zone.
        DateTimeFormatter formatter = new DateTimeFormatterBuilder()
                .appendYear()
                .appendLiteral(' ')
                .appendLiteral('Z') // This often triggers zone logic in parsers
                .toFormatter();

        org.joda.time.MutableDateTime instant = new org.joda.time.MutableDateTime();
        String text = "2023 Z";

        formatter.parseInto(instant, text, 0);
        // Verify it doesn't crash and processes position
        Assert.assertTrue(instant.getYear() == 2023);
    }

    @Test
    public void testParseInto_WithPivotYear() {
        // Test the branch: DateTimeParserBucket(..., iPivotYear, ...)
        DateTimeFormatter formatter = new DateTimeFormatterBuilder()
                .appendYearTwoDigit()
                .toFormatter()
                .withPivotYear(2000);

        org.joda.time.MutableDateTime instant = new org.joda.time.MutableDateTime();
        String text = "23"; // Should be 2023 because pivot is 2000

        formatter.parseInto(instant, text, 0);
        Assert.assertEquals(2023, instant.getYear());
    }

    @Test
    public void testParseInto_WithDefaultYear() {
        // Test the branch: int defaultYear = ...
        DateTimeFormatter formatter = new DateTimeFormatterBuilder()
                .appendMonthOfYear()
                .appendLiteral('/')
                .appendDayOfMonth()
                .toFormatter()
                .withDefaultYear(2025);

        org.joda.time.MutableDateTime instant = new org.joda.time.MutableDateTime();
        String text = "05/10";

        formatter.parseInto(instant, text, 0);
        Assert.assertEquals(2025, instant.getYear());
        Assert.assertEquals(5, instant.getMonthOfYear());
        Assert.assertEquals(10, instant.getDayOfMonth());
    }
}
